style.css:
@-moz-document domain("youtube.com") {
/* General Background */
    body, #page-manager, ytd-app {
        background-color: #181818 !important;
        color: #ffffff !important;
    }

    /* Header */
    #masthead-container, ytd-masthead {
        background-color: #202020 !important;
        border-bottom: 1px solid #333 !important;
    }

    /* Search Bar */
    #search-form {
        background-color: #333 !important;
    }

    #search-icon-legacy, #guide-icon {
        color: #ffffff !important;
    }

    /* Video Titles */
    #video-title, h3.title, h1.title {
        color: #ffffff !important;
    }

    /* Sidebar */
    #guide-content {
        background-color: #202020 !important;
        color: #ffffff !important;
    }

    /* Thumbnails */
    ytd-thumbnail {
        border: 1px solid #333 !important;
    }

    ytd-thumbnail:hover {
        border-color: #555 !important;
    }

    /* Like/Dislike and Subscribe Buttons */
    #top-level-buttons-computed ytd-toggle-button-renderer {
        color: #bbbbbb !important;
    }

    #subscribe-button {
        background-color: #cc0000 !important;
        color: #ffffff !important;
        border-radius: 4px;
        padding: 5px 10px;
    }

    #subscribe-button:hover {
        background-color: #ff0000 !important;
    }

    /* Comments Section */
    #comments, ytd-comment-thread-renderer {
        background-color: #202020 !important;
        border-top: 1px solid #333 !important;
        color: #ffffff !important;
    }

    ytd-comment-renderer #content-text {
        color: #cccccc !important;
    }

    /* Footer */
    #footer {
        background-color: #202020 !important;
        color: #888888 !important;
    }
}
